package com.prayeroverheads;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.HeadIcon;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Redraws the wanted 2D elements for every player whose vanilla block the draw
 * listener suppressed. Scene-level prayer replacements live in a separate overlay
 * so this UI can render after the scene and actor overhead passes.
 */
class PrayerOverheadsOverlay extends Overlay
{
	private static final int HEALTH_BAR_WIDTH = 30;
	private static final int HEALTH_BAR_HEIGHT = 5;
	private static final int HEALTH_BAR_RAISE = 15;
	private static final int ELEMENT_GAP = 2;
	private static final Color HEALTH_BAR_LOST = new Color(0xFF, 0x00, 0x00);
	private static final Color HEALTH_BAR_REMAINING = new Color(0x00, 0xFF, 0x00);
	private static final Color CHAT_TEXT = new Color(0xFF, 0xFF, 0x00);

	private static final int HITSPLAT_WIDTH = 21;
	private static final int HITSPLAT_HEIGHT = 15;
	// Vanilla splats sit above the player's midpoint rather than on it.
	private static final int HITSPLAT_RAISE = 45;

	private static final Color HITSPLAT_BLOCK = new Color(0x00, 0x64, 0xC8);
	private static final Color HITSPLAT_POISON = new Color(0x00, 0x96, 0x00);
	private static final Color HITSPLAT_VENOM = new Color(0x00, 0x50, 0x00);
	private static final Color HITSPLAT_DISEASE = new Color(0xC8, 0x96, 0x00);
	private static final Color HITSPLAT_HEAL = new Color(0x9B, 0x30, 0xC8);
	private static final Color HITSPLAT_DRAIN = new Color(0x64, 0x64, 0xC8);
	private static final Color HITSPLAT_CYAN = new Color(0x00, 0xB4, 0xB4);
	private static final Color HITSPLAT_ORANGE = new Color(0xE0, 0x78, 0x00);
	private static final Color HITSPLAT_YELLOW = new Color(0xC8, 0xC8, 0x00);
	private static final Color HITSPLAT_WHITE = new Color(0x96, 0x96, 0x96);
	private static final Color HITSPLAT_DAMAGE = new Color(0xC8, 0x00, 0x00);

	private final Client client;
	private final PrayerOverheadsPlugin plugin;
	private final PrayerOverheadsConfig config;
	private final SpriteManager spriteManager;

	private final TextComponent textComponent = new TextComponent();
	private final Map<Integer, HitsplatDefinition> hitsplatDefinitions = new HashMap<>();
	private final Map<Long, BufferedImage> compactOverheads = new HashMap<>();
	private final Map<Long, BufferedImage> overheadSprites = new HashMap<>();

	@Inject
	PrayerOverheadsOverlay(Client client, PrayerOverheadsPlugin plugin, PrayerOverheadsConfig config,
		SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;

		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}

		Widget filter = client.getWidget(InterfaceID.Chatbox.CHAT_PUBLIC_FILTER);
		String filterText = filter == null ? null : filter.getText();
		String chatMode = filterText == null ? "" : Text.removeTags(filterText).trim();
		List<ChatEntry> chatEntries = new ArrayList<>();
		for (Player player : worldView.players())
		{
			if (plugin.shouldHide2D(player) && !plugin.isPlayerHiddenByEntityHider(player))
			{
				renderPlayer(graphics, player, chatEntries, chatMode);
			}
		}

		layoutChatEntries(chatEntries);
		renderChatEntries(graphics, chatEntries);

		return null;
	}

	private void renderPlayer(Graphics2D graphics, Player player, List<ChatEntry> chatEntries, String chatMode)
	{
		boolean speaking = config.keepChatText() && collectChatEntry(graphics, player, chatEntries, chatMode);
		Point anchor = headPoint(graphics, player,
			player.getLogicalHeight() + config.heightOffset() + HEALTH_BAR_RAISE);
		if (anchor != null)
		{
			OverheadStack stack = new OverheadStack(anchor.getY(), speaking);
			boolean healthBar = config.keepHealthBar() && player.getHealthRatio() >= 0 && player.getHealthScale() > 0;
			if (healthBar)
			{
				renderHealthBar(graphics, player, anchor.getX(), stack.healthBar());
			}
			stack.finishHealthBars();
			if (config.keepSkull())
			{
				BufferedImage skull = overheadSprite(net.runelite.api.gameval.SpriteID.HEADICONS_PK, player.getSkullIcon());
				if (skull != null)
				{
					drawOverhead(graphics, skull, anchor.getX(), stack.icon(skull.getHeight()));
				}
			}
			HeadIcon icon = plugin.getHeadIcon(player);
			if (icon != null && config.showCompactOverhead())
			{
				BufferedImage prayer = compactOverhead(icon);
				if (prayer != null)
				{
					drawOverhead(graphics, prayer, anchor.getX(), stack.icon(prayer.getHeight()));
				}
			}
		}
		if (config.keepHitsplats())
		{
			renderHitsplats(graphics, player);
		}
	}

	private void drawOverhead(Graphics2D graphics, BufferedImage image, int centerX, int topY)
	{
		graphics.drawImage(image, centerX - image.getWidth() / 2, topY, null);
	}

	// Only the anchor is projected. These offsets are canvas pixels, independent of camera zoom.
	static final class OverheadStack
	{
		private final int anchorY;
		private int offset;

		OverheadStack(int anchorY, boolean speaking)
		{
			this.anchorY = anchorY;
			offset = speaking ? 10 : -2;
		}

		int healthBar()
		{
			offset += HEALTH_BAR_HEIGHT;
			int y = anchorY - offset;
			offset += ELEMENT_GAP;
			return y;
		}

		void finishHealthBars()
		{
			if (offset == -2)
			{
				offset = 5;
			}
		}

		int icon(int height)
		{
			offset += height + 1;
			return anchorY - offset;
		}
	}

	private void renderHitsplats(Graphics2D graphics, Player player)
	{
		// Vanilla uses four staggered slots rather than a single horizontal row. The
		// slot is fixed when the splat is tracked, so a splat does not move when an
		// earlier one expires.
		Point anchor = null;
		for (PrayerOverheadsPlugin.TrackedHitsplat tracked : plugin.getTrackedHitsplats())
		{
			if (tracked.actor != player)
			{
				continue;
			}

			if (anchor == null)
			{
				anchor = headPoint(graphics, player, player.getLogicalHeight() / 2 + HITSPLAT_RAISE);
				if (anchor == null)
				{
					return;
				}
			}

			int slot = tracked.slot;
			int xOffset = slot == 2 ? -15 : slot == 3 ? 15 : 0;
			int yOffset = slot == 1 ? -20 : slot >= 2 ? -10 : 0;
			renderHitsplat(graphics, tracked, anchor.getX() + xOffset, anchor.getY() + yOffset);
		}
	}

	/**
	 * Drops the sprite and definition caches. Called on shutdown so an unused plugin
	 * holds no decoded cache data or scaled images.
	 */
	void clearCaches()
	{
		hitsplatDefinitions.clear();
		compactOverheads.clear();
		overheadSprites.clear();
	}

	private void renderHitsplat(Graphics2D graphics, PrayerOverheadsPlugin.TrackedHitsplat tracked, int centerX, int centerY)
	{
		Hitsplat hitsplat = tracked.hitsplat;
		HitsplatDefinition definition = hitsplatDefinition(hitsplat.getHitsplatType());
		if (definition != null && definition.transforms != null)
		{
			int transformedId = definition.transformedId(client);
			definition = transformedId < 0 ? null : hitsplatDefinition(transformedId);
		}

		if (definition == null || !renderDefinedHitsplat(graphics, tracked, definition, centerX, centerY))
		{
			renderFallbackHitsplat(graphics, hitsplat, centerX, centerY);
		}
	}

	private HitsplatDefinition hitsplatDefinition(int id)
	{
		HitsplatDefinition definition = hitsplatDefinitions.get(id);
		if (!hitsplatDefinitions.containsKey(id))
		{
			definition = HitsplatDefinition.load(client, id);
			hitsplatDefinitions.put(id, definition);
		}
		return definition;
	}

	private boolean renderDefinedHitsplat(Graphics2D graphics, PrayerOverheadsPlugin.TrackedHitsplat tracked,
		HitsplatDefinition definition, int centerX, int centerY)
	{
		BufferedImage left = sprite(definition.leftSprite);
		BufferedImage icon = sprite(definition.iconSprite);
		BufferedImage middle = sprite(definition.middleSprite);
		BufferedImage right = sprite(definition.rightSprite);
		if (left == null && icon == null && middle == null && right == null)
		{
			return false;
		}

		Font originalFont = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();
		String amount = Integer.toString(tracked.hitsplat.getAmount());
		int textWidth = metrics.stringWidth(amount);
		int middleWidth = middle == null ? textWidth + 4 : middle.getWidth();
		int repeats = middle == null ? 1 : Math.max(1, (textWidth + middleWidth - 1) / middleWidth);
		int width = imageWidth(left) + imageWidth(icon) + repeats * middleWidth + imageWidth(right);
		int height = Math.max(metrics.getHeight(), Math.max(imageHeight(left), Math.max(imageHeight(icon),
			Math.max(imageHeight(middle), imageHeight(right)))));

		int elapsed = Math.max(0, client.getGameCycle() - tracked.appliedOnGameCycle);
		int duration = Math.max(1, tracked.hitsplat.getDisappearsOnGameCycle() - tracked.appliedOnGameCycle);
		float progress = Math.min(1f, elapsed / (float) duration);
		int x = centerX - width / 2 + Math.round(definition.scrollX * progress);
		int y = centerY - height / 2 - Math.round(definition.scrollY * progress);
		float opacity = 1f;
		if (definition.fadeStartCycle >= 0 && elapsed > definition.fadeStartCycle)
		{
			opacity = Math.max(0f, 1f - (elapsed - definition.fadeStartCycle)
				/ (float) Math.max(1, duration - definition.fadeStartCycle));
		}

		Composite originalComposite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
		int cursor = x;
		cursor = drawSprite(graphics, left, cursor, y, height);
		cursor = drawSprite(graphics, icon, cursor, y, height);
		int textAreaX = cursor;
		if (middle != null)
		{
			for (int i = 0; i < repeats; i++)
			{
				graphics.drawImage(middle, cursor, y + (height - middle.getHeight()) / 2, null);
				cursor += middleWidth;
			}
		}
		else
		{
			cursor += middleWidth;
		}
		drawSprite(graphics, right, cursor, y, height);

		int textX = textAreaX + (repeats * middleWidth - textWidth) / 2;
		int baseline = y + (height - metrics.getHeight()) / 2 + metrics.getAscent() + definition.textOffsetY;
		graphics.setColor(Color.BLACK);
		graphics.drawString(amount, textX + 1, baseline + 1);
		graphics.setColor(definition.textColorAwt());
		graphics.drawString(amount, textX, baseline);
		graphics.setComposite(originalComposite);
		graphics.setFont(originalFont);
		return true;
	}

	private void renderFallbackHitsplat(Graphics2D graphics, Hitsplat hitsplat, int centerX, int centerY)
	{
		int x = centerX - HITSPLAT_WIDTH / 2;
		int y = centerY - HITSPLAT_HEIGHT / 2;
		graphics.setColor(hitsplatColor(hitsplat.getHitsplatType()));
		graphics.fillOval(x, y, HITSPLAT_WIDTH - 1, HITSPLAT_HEIGHT - 1);

		String amount = Integer.toString(hitsplat.getAmount());
		int textWidth = graphics.getFontMetrics().stringWidth(amount);
		int baseline = y + (HITSPLAT_HEIGHT + graphics.getFontMetrics().getAscent()) / 2 - 1;

		textComponent.setText(amount);
		textComponent.setColor(Color.WHITE);
		textComponent.setPosition(new java.awt.Point(x + (HITSPLAT_WIDTH - textWidth) / 2, baseline));
		textComponent.render(graphics);
	}

	private BufferedImage sprite(int spriteId)
	{
		return spriteId < 0 ? null : spriteManager.getSprite(spriteId, 0);
	}

	private int drawSprite(Graphics2D graphics, BufferedImage sprite, int x, int y, int height)
	{
		if (sprite == null)
		{
			return x;
		}
		graphics.drawImage(sprite, x, y + (height - sprite.getHeight()) / 2, null);
		return x + sprite.getWidth();
	}

	private int imageWidth(BufferedImage image)
	{
		return image == null ? 0 : image.getWidth();
	}

	private int imageHeight(BufferedImage image)
	{
		return image == null ? 0 : image.getHeight();
	}

	/**
	 * Approximates the vanilla hitsplat palette. The client keys these off sprite ids
	 * that the API does not expose, so the mapping is by hitsplat type instead.
	 */
	private Color hitsplatColor(int type)
	{
		if (type == HitsplatID.BLOCK_ME || type == HitsplatID.BLOCK_OTHER || type == HitsplatID.DISEASE_BLOCKED)
		{
			return HITSPLAT_BLOCK;
		}
		if (type == HitsplatID.POISON)
		{
			return HITSPLAT_POISON;
		}
		if (type == HitsplatID.VENOM)
		{
			return HITSPLAT_VENOM;
		}
		if (type == HitsplatID.DISEASE)
		{
			return HITSPLAT_DISEASE;
		}
		if (type == HitsplatID.HEAL)
		{
			return HITSPLAT_HEAL;
		}
		if (type == HitsplatID.PRAYER_DRAIN || type == HitsplatID.SANITY_DRAIN || type == HitsplatID.SANITY_RESTORE)
		{
			return HITSPLAT_DRAIN;
		}
		if (type == HitsplatID.DAMAGE_ME_CYAN || type == HitsplatID.DAMAGE_OTHER_CYAN
			|| type == HitsplatID.DAMAGE_MAX_ME_CYAN || type == HitsplatID.CYAN_UP || type == HitsplatID.CYAN_DOWN)
		{
			return HITSPLAT_CYAN;
		}
		if (type == HitsplatID.DAMAGE_ME_ORANGE || type == HitsplatID.DAMAGE_OTHER_ORANGE
			|| type == HitsplatID.DAMAGE_MAX_ME_ORANGE || type == HitsplatID.BURN)
		{
			return HITSPLAT_ORANGE;
		}
		if (type == HitsplatID.DAMAGE_ME_YELLOW || type == HitsplatID.DAMAGE_OTHER_YELLOW
			|| type == HitsplatID.DAMAGE_MAX_ME_YELLOW)
		{
			return HITSPLAT_YELLOW;
		}
		if (type == HitsplatID.DAMAGE_ME_WHITE || type == HitsplatID.DAMAGE_OTHER_WHITE
			|| type == HitsplatID.DAMAGE_MAX_ME_WHITE)
		{
			return HITSPLAT_WHITE;
		}

		// Everything else, including the plain and max-hit damage splats.
		return HITSPLAT_DAMAGE;
	}

	private BufferedImage compactOverhead(HeadIcon icon)
	{
		int scale = config.iconScale();
		long cacheKey = ((long) icon.ordinal() << 32) | (scale & 0xFFFFFFFFL);
		BufferedImage sprite = compactOverheads.get(cacheKey);
		if (sprite == null)
		{
			BufferedImage original = overheadSprite(
				net.runelite.api.gameval.SpriteID.HEADICONS_PRAYER, icon.ordinal());
			if (original == null)
			{
				return null;
			}
			int width = Math.max(1, original.getWidth() * scale / 100);
			int height = Math.max(1, original.getHeight() * scale / 100);
			sprite = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			Graphics2D scaledGraphics = sprite.createGraphics();
			scaledGraphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			scaledGraphics.drawImage(original, 0, 0, width, height, null);
			scaledGraphics.dispose();
			compactOverheads.put(cacheKey, sprite);
		}

		return sprite;
	}

	private BufferedImage overheadSprite(int archive, int file)
	{
		if (file < 0)
		{
			return null;
		}
		long key = ((long) archive << 32) | (file & 0xFFFFFFFFL);
		BufferedImage image = overheadSprites.get(key);
		if (image == null)
		{
			SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), archive, 0);
			if (sprites == null || file >= sprites.length || sprites[file] == null)
			{
				return null;
			}
			SpritePixels sprite = sprites[file];
			image = normalizedSprite(sprite);
			overheadSprites.put(key, image);
		}
		return image;
	}

	static BufferedImage normalizedSprite(SpritePixels sprite)
	{
		BufferedImage image = new BufferedImage(Math.max(1, sprite.getMaxWidth()),
			Math.max(1, sprite.getMaxHeight()), BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(sprite.toBufferedImage(), sprite.getOffsetX(), sprite.getOffsetY(), null);
		graphics.dispose();
		return image;
	}

	private boolean collectChatEntry(Graphics2D graphics, Player player, List<ChatEntry> entries, String chatMode)
	{
		if (!plugin.shouldShowChat(player, chatMode))
		{
			return false;
		}
		Point anchor = headPoint(graphics, player, player.getLogicalHeight() + config.heightOffset());
		if (anchor == null)
		{
			return false;
		}
		String text = Text.unescapeJagex(player.getOverheadText());
		FontMetrics metrics = graphics.getFontMetrics(FontManager.getRunescapeBoldFont());
		entries.add(new ChatEntry(text, anchor.getX(), anchor.getY() + 2,
			metrics.stringWidth(text) / 2, metrics.getAscent()));
		return true;
	}

	private void renderChatEntries(Graphics2D graphics, List<ChatEntry> entries)
	{
		Font originalFont = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeBoldFont());
		for (ChatEntry entry : entries)
		{
			int x = entry.centerX - entry.halfWidth;
			graphics.setColor(Color.BLACK);
			graphics.drawString(entry.text, x + 1, entry.y + 1);
			graphics.setColor(CHAT_TEXT);
			graphics.drawString(entry.text, x, entry.y);
		}
		graphics.setFont(originalFont);
	}

	static void layoutChatEntries(List<ChatEntry> entries)
	{
		for (int i = 0; i < entries.size(); i++)
		{
			ChatEntry current = entries.get(i);
			boolean moved;
			do
			{
				moved = false;
				for (int j = 0; j < i; j++)
				{
					ChatEntry previous = entries.get(j);
					if (current.y + 2 > previous.y - previous.height
						&& current.y - current.height < previous.y + 2
						&& current.centerX - current.halfWidth < previous.centerX + previous.halfWidth
						&& current.centerX + current.halfWidth > previous.centerX - previous.halfWidth
						&& previous.y - previous.height < current.y)
					{
						current.y = previous.y - previous.height;
						moved = true;
					}
				}
			}
			while (moved);
		}
	}

	private void renderHealthBar(Graphics2D graphics, Player player, int centerX, int y)
	{
		int ratio = player.getHealthRatio();
		int scale = player.getHealthScale();
		int x = centerX - HEALTH_BAR_WIDTH / 2;
		int remaining = healthBarFillWidth(ratio, scale, HEALTH_BAR_WIDTH);

		graphics.setColor(HEALTH_BAR_LOST);
		graphics.fillRect(x, y, HEALTH_BAR_WIDTH, HEALTH_BAR_HEIGHT);
		graphics.setColor(HEALTH_BAR_REMAINING);
		graphics.fillRect(x, y, remaining, HEALTH_BAR_HEIGHT);
	}

	static int healthBarFillWidth(int ratio, int scale, int width)
	{
		if (ratio < 0 || scale <= 0 || width <= 0)
		{
			return 0;
		}
		long clampedRatio = Math.min((long) ratio, (long) scale);
		int fill = (int) (clampedRatio * width / scale);
		return ratio > 0 ? Math.max(1, fill) : 0;
	}

	static final class ChatEntry
	{
		final String text;
		final int centerX;
		final int halfWidth;
		final int height;
		int y;

		ChatEntry(String text, int centerX, int y, int halfWidth, int height)
		{
			this.text = text;
			this.centerX = centerX;
			this.y = y;
			this.halfWidth = halfWidth;
			this.height = height;
		}
	}

	static Point headPoint(Graphics2D graphics, Player player, int zOffset)
	{
		// Actor projection accounts for the player's world view, footprint tile
		// height, and animation height offset. A raw tile projection does not.
		return player.getCanvasTextLocation(graphics, "", zOffset);
	}

}

package com.prayeroverheads;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.HeadIcon;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Draws the scene-level prayer replacements. These stay immediately above the
 * scene so they cannot cover actor overheads or the plugin's redrawn 2D UI.
 */
class PrayerOverheadsSceneOverlay extends Overlay
{
	private final Client client;
	private final PrayerOverheadsPlugin plugin;
	private final PrayerOverheadsConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	// Render-path scratch state: the inputs repeat every frame, so the derived
	// AWT objects are memoised rather than reallocated per player per frame.
	private final Map<Long, Color> highlightColors = new HashMap<>();
	private Stroke tileBorderStroke;
	private int tileBorderStrokeWidth = -1;

	@Inject
	PrayerOverheadsSceneOverlay(Client client, PrayerOverheadsPlugin plugin, PrayerOverheadsConfig config,
		ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;

		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}

		for (Player player : worldView.players())
		{
			if (!plugin.shouldHide2D(player) || plugin.isPlayerHiddenByEntityHider(player))
			{
				continue;
			}

			HeadIcon icon = plugin.getHeadIcon(player);
			if (icon != null)
			{
				renderPrayerDisplay(graphics, player, icon);
			}
		}

		return null;
	}

	void clearCaches()
	{
		highlightColors.clear();
		tileBorderStroke = null;
		tileBorderStrokeWidth = -1;
	}

	private void renderPrayerDisplay(Graphics2D graphics, Player player, HeadIcon icon)
	{
		Color color = highlightColor(colorFor(icon), config.highlightOpacity());
		if (config.showTile())
		{
			renderTile(graphics, player, color);
		}
		if (config.showOutline())
		{
			outlineRenderer.drawOutline(player, config.outlineWidth(), color, config.outlineFeather());
		}
	}

	private Color highlightColor(Color color, int opacityPercent)
	{
		long key = ((long) color.getRGB() << 32) | (opacityPercent & 0xFFFFFFFFL);
		return highlightColors.computeIfAbsent(key, k -> withHighlightOpacity(color, opacityPercent));
	}

	private void renderTile(Graphics2D graphics, Player player, Color color)
	{
		Polygon poly = player.getCanvasTilePoly();
		if (poly == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.fill(poly);

		int borderWidth = config.tileBorderWidth();
		if (borderWidth > 0)
		{
			Stroke original = graphics.getStroke();
			graphics.setColor(color);
			graphics.setStroke(tileBorderStroke(borderWidth));
			graphics.draw(poly);
			graphics.setStroke(original);
		}
	}

	private Stroke tileBorderStroke(int width)
	{
		if (tileBorderStroke == null || tileBorderStrokeWidth != width)
		{
			tileBorderStroke = new BasicStroke(width);
			tileBorderStrokeWidth = width;
		}
		return tileBorderStroke;
	}

	static Color withHighlightOpacity(Color color, int opacityPercent)
	{
		int alpha = color.getAlpha() * opacityPercent / 100;
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	private Color colorFor(HeadIcon icon)
	{
		switch (icon)
		{
			case MELEE:
			case DEFLECT_MELEE:
				return config.meleeColor();
			case RANGED:
			case DEFLECT_RANGE:
				return config.rangedColor();
			case MAGIC:
			case DEFLECT_MAGE:
				return config.magicColor();
			default:
				return config.otherColor();
		}
	}
}

package com.prayeroverheads;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HeadIcon;
import net.runelite.api.Hitsplat;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.entityhider.EntityHiderConfig;
import net.runelite.client.plugins.entityhider.EntityHiderPlugin;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Overheads Reworked",
	description = "Replace the large overhead protection prayer bubbles with a subtle display",
	tags = {"prayer", "overhead", "hide", "raid", "declutter"}
)
public class PrayerOverheadsPlugin extends Plugin
{
	/**
	 * Vanilla stacks at most four splats on an actor at once, in four fixed slots.
	 */
	static final int MAX_HITSPLATS = 4;

	@Inject
	private Client client;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private PartyService partyService;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PrayerOverheadsOverlay overlay;

	@Inject
	private PrayerOverheadsSceneOverlay sceneOverlay;

	@Inject
	private PrayerOverheadsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	private EntityHiderConfig entityHiderConfig;
	private Plugin entityHiderPlugin;

	// The listener runs on the client thread for every renderable of every frame,
	// so config is read from plain fields rather than through the proxy.
	private boolean hideSelf2D;
	private boolean hideParty2D;
	private boolean hideOthers2D;
	private boolean onlyWhilePraying;
	private boolean replaceSmite;
	private boolean replaceRedemption;
	private boolean replaceRetribution;
	private boolean keepHitsplats;

	// RenderCallback has only default methods, so it is not a functional interface.
	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean drawingUI)
		{
			return shouldDraw(renderable, drawingUI);
		}
	};

	/**
	 * Hitsplats applied to actors whose 2D block is hidden, held until the game cycle
	 * the client would have removed them on. Only a few live at once — they expire
	 * within a couple of ticks — so a flat list beats a per-actor map here.
	 */
	private final List<TrackedHitsplat> trackedHitsplats = new ArrayList<>();
	private final OverheadChat overheadChat = new OverheadChat();

	@Provides
	PrayerOverheadsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PrayerOverheadsConfig.class);
	}

	@Override
	protected void startUp()
	{
		cacheConfig();
		entityHiderConfig = configManager.getConfig(EntityHiderConfig.class);
		findEntityHiderPlugin();
		overlayManager.add(sceneOverlay);
		overlayManager.add(overlay);
		renderCallbackManager.register(renderCallback);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
		overlayManager.remove(overlay);
		overlayManager.remove(sceneOverlay);
		overlay.clearCaches();
		sceneOverlay.clearCaches();
		trackedHitsplats.clear();
		overheadChat.clear();
		entityHiderPlugin = null;
		entityHiderConfig = null;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		// Recorded only for actors already being hidden: if the actor's 2D block is
		// visible, the client is drawing its hitsplat itself.
		if (!keepHitsplats || !shouldHide2D(event.getActor()))
		{
			return;
		}

		int slot = nextHitsplatSlot(event.getActor());
		if (slot < 0)
		{
			// All four vanilla slots are occupied; the client would not draw a fifth either.
			return;
		}

		trackedHitsplats.add(new TrackedHitsplat(event.getActor(), event.getHitsplat(), client.getGameCycle(), slot));
	}

	/**
	 * The lowest slot this actor is not already using, or -1 if all are taken. Assigning
	 * the slot once and holding it for the splat's lifetime keeps it in place when an
	 * earlier splat expires — an index into a per-frame list would shift it mid-flight.
	 */
	private int nextHitsplatSlot(Actor actor)
	{
		boolean[] taken = new boolean[MAX_HITSPLATS];
		for (TrackedHitsplat tracked : trackedHitsplats)
		{
			if (tracked.actor == actor)
			{
				taken[tracked.slot] = true;
			}
		}

		for (int slot = 0; slot < MAX_HITSPLATS; slot++)
		{
			if (!taken[slot])
			{
				return slot;
			}
		}

		return -1;
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		int cycle = client.getGameCycle();
		overheadChat.expire(cycle);
		trackedHitsplats.removeIf(tracked -> cycle >= tracked.hitsplat.getDisappearsOnGameCycle());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Actor references do not survive a scene reload.
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			trackedHitsplats.clear();
			overheadChat.clear();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		overheadChat.message(event.getName(), event.getType(), client.getGameCycle());
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (event.getActor() instanceof Player)
		{
			// The actor update precedes its ChatMessage event, which supplies the new type.
			overheadChat.textChanged(event.getActor().getName());
		}
	}

	boolean shouldShowChat(Player player, String mode)
	{
		String text = player.getOverheadText();
		if (text == null || text.trim().isEmpty() || player.getOverheadCycle() <= 0)
		{
			return false;
		}
		if (player == client.getLocalPlayer())
		{
			return true;
		}
		String name = player.getName();
		if (name == null || client.getIgnoreContainer().findByName(name) != null)
		{
			return false;
		}
		return overheadChat.visible(mode, name, player.isFriend(), client.getGameCycle());
	}

	List<TrackedHitsplat> getTrackedHitsplats()
	{
		return trackedHitsplats;
	}

	static class TrackedHitsplat
	{
		final Actor actor;
		final Hitsplat hitsplat;
		final int appliedOnGameCycle;
		/** Fixed for this splat's lifetime; see {@link #nextHitsplatSlot(Actor)}. */
		final int slot;

		TrackedHitsplat(Actor actor, Hitsplat hitsplat, int appliedOnGameCycle, int slot)
		{
			this.actor = actor;
			this.hitsplat = hitsplat;
			this.appliedOnGameCycle = appliedOnGameCycle;
			this.slot = slot;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PrayerOverheadsConfig.GROUP.equals(event.getGroup()))
		{
			cacheConfig();
		}
	}

	private void cacheConfig()
	{
		hideSelf2D = config.hideSelf2D();
		hideParty2D = config.hideParty2D();
		hideOthers2D = config.hideOthers2D();
		onlyWhilePraying = config.onlyWhilePraying();
		replaceSmite = config.replaceSmite();
		replaceRedemption = config.replaceRedemption();
		replaceRetribution = config.replaceRetribution();
		keepHitsplats = config.keepHitsplats();
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		// drawingUI is the actor's 2D pass (overhead chat, health bar, prayer bubble,
		// skull) as one block. The 3D model pass must never be touched.
		if (!drawingUI || !(renderable instanceof Actor))
		{
			return true;
		}

		return !shouldHide2D((Actor) renderable);
	}

	/**
	 * Whether this actor's vanilla 2D block is suppressed right now. Used both by the
	 * draw listener and by the overlay, so the two always agree on the same frame.
	 *
	 * <p>The plugin is player-only by design: NPCs keep their vanilla 2D block in full.
	 */
	boolean shouldHide2D(Actor actor)
	{
		if (!(actor instanceof Player))
		{
			return false;
		}

		Player player = (Player) actor;
		HeadIcon icon = getHeadIcon(player);
		if (icon != null && !shouldReplace(icon))
		{
			// Leave the complete vanilla 2D pass intact for excluded prayers.
			return false;
		}

		if (!hideCategory(player))
		{
			return false;
		}

		return !onlyWhilePraying || icon != null;
	}

	private boolean shouldReplace(HeadIcon icon)
	{
		switch (icon)
		{
			case SMITE:
				return replaceSmite;
			case REDEMPTION:
				return replaceRedemption;
			case RETRIBUTION:
				return replaceRetribution;
			default:
				return true;
		}
	}

	/**
	 * Entity Hider owns visibility. Its render listener suppresses the model/2D
	 * passes, but overlays run later and cannot observe that combined listener
	 * result, so mirror its player-category decision before drawing replacements.
	 */
	boolean isPlayerHiddenByEntityHider(Player player)
	{
		if (entityHiderConfig == null || !isEntityHiderActive() || player.getName() == null)
		{
			return false;
		}

		Player localPlayer = client.getLocalPlayer();
		if (player == localPlayer)
		{
			return entityHiderConfig.hideLocalPlayer() || entityHiderConfig.hideLocalPlayer2D();
		}

		if (entityHiderConfig.hideAttackers() && player.getInteracting() == localPlayer)
		{
			return true;
		}

		String name = player.getName();
		if (partyService.isInParty() && partyService.getMemberByDisplayName(name) != null)
		{
			return entityHiderConfig.hidePartyMembers();
		}
		if (player.isFriend())
		{
			return entityHiderConfig.hideFriends();
		}
		if (player.isFriendsChatMember())
		{
			return entityHiderConfig.hideFriendsChatMembers();
		}
		if (player.isClanMember())
		{
			return entityHiderConfig.hideClanChatMembers();
		}
		if (client.getIgnoreContainer().findByName(name) != null)
		{
			return entityHiderConfig.hideIgnores();
		}

		return entityHiderConfig.hideOthers() || entityHiderConfig.hideOthers2D();
	}

	private boolean isEntityHiderActive()
	{
		if (entityHiderPlugin == null)
		{
			findEntityHiderPlugin();
		}
		return entityHiderPlugin != null && pluginManager.isPluginActive(entityHiderPlugin);
	}

	private void findEntityHiderPlugin()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof EntityHiderPlugin)
			{
				entityHiderPlugin = plugin;
				return;
			}
		}
	}

	private boolean hideCategory(Player player)
	{
		if (player == client.getLocalPlayer())
		{
			return hideSelf2D;
		}

		// Names are null for players the client hasn't resolved yet; party lookup NPEs on those.
		String name = player.getName();
		if (name == null)
		{
			return false;
		}

		if (hideParty2D && partyService.isInParty() && partyService.getMemberByDisplayName(name) != null)
		{
			return true;
		}

		return hideOthers2D;
	}

	/**
	 * The overhead icon a player is currently showing, or null for none.
	 *
	 * <p>Deliberately the same for the local player as for everyone else: using the
	 * prayer varbits instead would light this up a tick before {@link Player#getOverheadIcon()}
	 * actually changes, i.e. before the protection is mechanically active.
	 */
	HeadIcon getHeadIcon(Player player)
	{
		return player.getOverheadIcon();
	}
}

